<template>
  <LabToolPage :meta="meta">
    <section class="lab-workspace color-workspace" aria-labelledby="color-workspace-title">
      <div class="lab-panel color-controls-panel">
        <div class="lab-panel-heading"><div><p class="card-kicker">01 · SAMPLE</p><h2 id="color-workspace-title">从照片里取一组颜色</h2></div><span class="lab-step">本地</span></div>
        <div class="lab-dropzone color-dropzone" :class="{ 'is-dragging': isDragging, 'has-file': file }" tabindex="0" @dragenter.prevent="isDragging = true" @dragover.prevent="isDragging = true" @dragleave.prevent="isDragging = false" @drop.prevent="handleDrop">
          <input ref="fileInput" type="file" accept="image/jpeg,image/png,image/webp" class="sr-only" @change="handleInput"><span class="lab-drop-icon" aria-hidden="true">◌</span><strong>{{ file ? file.name : isDragging ? '松开即可读取图片' : '把照片放到这张纸上' }}</strong><span>{{ file ? '透明像素会被忽略' : '支持 JPG、PNG、WebP · 单图处理' }}</span><button class="lab-button is-secondary" type="button" @click="fileInput?.click()">{{ file ? '重新选择图片' : '选择图片' }}</button>
        </div>
        <p v-if="errorMessage" class="lab-message is-error" role="alert">{{ errorMessage }}</p>
        <div class="lab-setting-group"><div class="lab-setting-heading"><strong>色板数量</strong><output>{{ colorCount }} 色</output></div><div class="lab-preset-row"><button v-for="count in [3, 5, 8]" :key="count" type="button" class="lab-chip" :class="{ active: colorCount === count }" @click="colorCount = count">{{ count }} 色</button></div><button v-if="file" class="lab-button is-secondary lab-full-button" type="button" :disabled="state === 'processing'" @click="extractColors">{{ state === 'processing' ? '正在提取…' : '重新提取颜色' }}</button></div>
        <div v-if="colors.length >= 2" class="lab-setting-group"><div class="lab-setting-heading"><strong>对比度检查</strong><small>任意两色组合</small></div><div class="lab-number-grid\"><label><span>背景色</span><select v-model.number="contrastFirst" class="lab-select"><option v-for="(color, index) in colors" :key="'a' + color.hex" :value="index">{{ color.hex }}</option></select></label><label><span>文字色</span><select v-model.number="contrastSecond" class="lab-select"><option v-for="(color, index) in colors" :key="'b' + color.hex" :value="index">{{ color.hex }}</option></select></label></div><div class="contrast-result"><strong>{{ contrastValue.toFixed(2) }}:1</strong><span>{{ contrastValue >= 7 ? '普通文字 AA · AAA 通过' : contrastValue >= 4.5 ? '普通文字 AA 通过 · 大号文字 AA 通过' : contrastValue >= 3 ? '仅大号文字 AA 通过' : '建议换一组颜色' }}</span></div></div>
        <div class="lab-setting-group"><div class="lab-setting-heading"><strong>导出</strong><small>结果不含原图</small></div><div class="lab-button-row"><button class="lab-button is-secondary" type="button" :disabled="!colors.length" @click="copyCss">{{ copied === 'css' ? '已复制 CSS' : '复制 CSS' }}</button><button class="lab-button is-secondary" type="button" :disabled="!colors.length" @click="copyJson">{{ copied === 'json' ? '已复制 JSON' : '复制 JSON' }}</button></div><button class="lab-button is-secondary lab-full-button" type="button" :disabled="!colors.length" @click="downloadPalette">下载色卡图片</button></div>
        <p class="lab-privacy-line"><span aria-hidden="true">⌁</span>图片只在当前浏览器中读取，不会上传服务器。</p>
      </div>
      <div class="lab-panel color-result-panel" aria-live="polite">
        <div class="lab-panel-heading"><div><p class="card-kicker">02 · PALETTE</p><h2>你的颜色手账</h2></div><span v-if="colors.length" class="lab-status is-success">{{ colors.length }} 个主色</span></div>
        <div v-if="!colors.length" class="lab-empty-result"><span aria-hidden="true">◌</span><h3>还没有色板</h3><p>选一张照片，颜色会在本地被整理成可以带走的设计资产。</p></div>
        <template v-else><div class="color-source-preview"><img :src="sourceUrl" alt="正在取色的照片预览"></div><div class="color-swatch-grid"><button v-for="(color, index) in colors" :key="color.hex" type="button" class="color-swatch-card" @click="toggleDetails(index)"><span class="color-swatch" :style="{ backgroundColor: color.hex }"><small>{{ index + 1 }}</small></span><strong>{{ color.hex }}</strong><small>点击复制 · {{ expandedIndex === index ? '收起详情' : '查看 RGB / HSL' }}</small><div v-if="expandedIndex === index" class="color-details"><span>RGB {{ color.rgb }}</span><span>HSL {{ color.hsl }}</span></div></button></div><section class="theme-preview"><div class="lab-panel-heading"><div><p class="card-kicker">LEVI THEME</p><h3>生成手账主题</h3></div><button class="lab-text-button" type="button" @click="copyTheme">复制主题</button></div><div class="theme-preview-card" :style="{ '--theme-paper': themeColors.paper, '--theme-ink': themeColors.ink, '--theme-sage': themeColors.sage, '--theme-forest': themeColors.forest, '--theme-apricot': themeColors.apricot }"><span class="theme-mini-label">A LITTLE NOTE</span><h4>把颜色留给下一页</h4><p>这组颜色可以成为一个局部主题，不会修改博客全局配色。</p><button type="button">保存这一页</button><span class="theme-tag"># color DNA</span></div></section></template>
      </div>
    </section>
  </LabToolPage>
</template>

<script setup lang="ts">
import { contrastRatio, hexToRgb, isSupportedImage, rgbToHex, rgbToHsl } from '~/utils/lab'
import { labTools } from '~/data/lab-tools'
const meta = labTools.find((tool) => tool.id === 'color')!
interface PaletteColor { hex: string; rgb: string; hsl: string; r: number; g: number; b: number }
const fileInput = ref<HTMLInputElement>(); const file = ref<File | null>(null); const sourceUrl = ref(''); const errorMessage = ref(''); const isDragging = ref(false); const state = ref<'idle' | 'processing'>('idle'); const colorCount = ref(5); const colors = ref<PaletteColor[]>([]); const expandedIndex = ref(-1); const contrastFirst = ref(0); const contrastSecond = ref(1); const copied = ref<'css' | 'json' | 'theme' | ''>('')
const contrastValue = computed(() => colors.value.length >= 2 ? contrastRatio(colors.value[contrastFirst.value]?.hex || '#000000', colors.value[contrastSecond.value]?.hex || '#ffffff') : 1)
const themeColors = computed(() => { const values = colors.value.map((color) => color.hex); return { paper: values[0] || '#F7F2E8', ink: values[values.length - 1] || '#2F3B32', sage: values[1] || '#7F9B82', forest: values[2] || '#365643', apricot: values[3] || '#DCA47F' } })
const cssOutput = computed(() => ':root {\\n  --paper: ' + themeColors.value.paper + ';\\n  --ink: ' + themeColors.value.ink + ';\\n  --sage: ' + themeColors.value.sage + ';\\n  --forest: ' + themeColors.value.forest + ';\\n  --apricot: ' + themeColors.value.apricot + ';\\n}')
const jsonOutput = computed(() => JSON.stringify(colors.value.map(({ hex, rgb, hsl }) => ({ hex, rgb, hsl })), null, 2))
function setError(message: string) { errorMessage.value = message }
function readImage(candidate: File) { if (!isSupportedImage(candidate)) return setError('图片格式暂不支持，请选择 JPG、PNG 或 WebP。'); if (candidate.size > 30 * 1024 * 1024) return setError('图片超过 30 MB，请选择体积更小的图片。'); const url = URL.createObjectURL(candidate); const image = new Image(); image.onload = () => { if (sourceUrl.value) URL.revokeObjectURL(sourceUrl.value); file.value = candidate; sourceUrl.value = url; extractColors(image) }; image.onerror = () => { URL.revokeObjectURL(url); setError('无法读取这张图片，请换一张再试。') }; image.src = url }
function handleInput(event: Event) { const candidate = (event.target as HTMLInputElement).files?.[0]; if (candidate) readImage(candidate); (event.target as HTMLInputElement).value = '' }
function handleDrop(event: DragEvent) { isDragging.value = false; const candidate = event.dataTransfer?.files?.[0]; if (candidate) readImage(candidate) }
function extractColors(loadedImage?: HTMLImageElement) { if (!file.value && !loadedImage) return; state.value = 'processing'; errorMessage.value = ''; const image = loadedImage || (() => { const value = new Image(); value.src = sourceUrl.value; return value })(); const run = () => { const canvas = document.createElement('canvas'); const scale = Math.min(1, 800 / Math.max(image.width, image.height)); canvas.width = Math.max(1, Math.round(image.width * scale)); canvas.height = Math.max(1, Math.round(image.height * scale)); const context = canvas.getContext('2d', { willReadFrequently: true })!; context.drawImage(image, 0, 0, canvas.width, canvas.height); const pixels = context.getImageData(0, 0, canvas.width, canvas.height).data; const buckets = new Map<string, { r: number; g: number; b: number; count: number }>(); for (let index = 0; index < pixels.length; index += 16) { const alpha = pixels[index + 3]; if (alpha < 20) continue; const r = Math.round(pixels[index] / 24) * 24; const g = Math.round(pixels[index + 1] / 24) * 24; const b = Math.round(pixels[index + 2] / 24) * 24; const key = r + ',' + g + ',' + b; const existing = buckets.get(key) || { r, g, b, count: 0 }; existing.count += 1; buckets.set(key, existing) } const ranked = [...buckets.values()].sort((a, b) => b.count - a.count); const selected: typeof ranked = []; for (const candidate of ranked) { if (selected.every((item) => Math.abs(item.r - candidate.r) + Math.abs(item.g - candidate.g) + Math.abs(item.b - candidate.b) > 48)) selected.push(candidate); if (selected.length >= colorCount.value) break } colors.value = selected.map((color) => { const hex = rgbToHex(color.r, color.g, color.b); const hsl = rgbToHsl(color.r, color.g, color.b); return { hex, r: color.r, g: color.g, b: color.b, rgb: color.r + ', ' + color.g + ', ' + color.b, hsl: hsl.h + '°, ' + hsl.s + '%, ' + hsl.l + '%' } }); state.value = 'idle'; contrastFirst.value = 0; contrastSecond.value = colors.value.length > 1 ? 1 : 0 }; if (image.complete) run(); else image.onload = run }
function toggleDetails(index: number) { expandedIndex.value = expandedIndex.value === index ? -1 : index; if (colors.value[index]) copyText(colors.value[index].hex) }
async function copyText(value: string) { try { await navigator.clipboard.writeText(value) } catch { const input = document.createElement('textarea'); input.value = value; document.body.appendChild(input); input.select(); document.execCommand('copy'); input.remove() } }
async function showCopied(kind: 'css' | 'json' | 'theme', value: string) { await copyText(value); copied.value = kind; window.setTimeout(() => { copied.value = '' }, 1600) }
function copyCss() { showCopied('css', cssOutput.value) }; function copyJson() { showCopied('json', jsonOutput.value) }; function copyTheme() { showCopied('theme', cssOutput.value) }
function downloadPalette() { const canvas = document.createElement('canvas'); canvas.width = 1200; canvas.height = 720; const context = canvas.getContext('2d')!; context.fillStyle = themeColors.value.paper; context.fillRect(0, 0, canvas.width, canvas.height); context.fillStyle = themeColors.value.ink; context.font = '52px Georgia, serif'; context.fillText('LEVI LAB · COLOR DNA', 80, 100); colors.value.forEach((color, index) => { const x = 80 + index % 4 * 270; const y = 170 + Math.floor(index / 4) * 230; context.fillStyle = color.hex; context.fillRect(x, y, 220, 150); context.fillStyle = themeColors.value.ink; context.font = '24px sans-serif'; context.fillText(color.hex, x, y + 190) }); const link = document.createElement('a'); link.href = canvas.toDataURL('image/png'); link.download = 'levi-lab-palette.png'; link.click() }
onBeforeUnmount(() => { if (sourceUrl.value) URL.revokeObjectURL(sourceUrl.value) })
useBlogSeo({ title: '图片取色与主题生成', description: '从一张照片提取 3、5 或 8 个主色，查看 HEX、RGB、HSL、对比度，并复制 CSS 与 JSON。', canonical: '/lab/color', keywords: '图片取色,色板生成,CSS变量,颜色对比度', breadcrumbs: [{ name: '手账实验室', path: '/lab' }, { name: meta.name, path: meta.path }] })
</script>
